    def alter_table_schema(self) -> bool:
        """
        Stage 1: Alter table schema to support new structure.
        Returns True if successful, False otherwise.
        """
        pass

    @abstractmethod
    def update_orm_entity(self) -> bool:
        """
        Stage 2: Update ORM entity with new fields/relationships.
        Returns True if successful, False otherwise.
        """
        pass

    @abstractmethod
    def adapt_rest_controller(self) -> bool:
        """
        Stage 3: Adapt REST controller to handle new schema.
        Returns True if successful, False otherwise.
        """
        pass

    def execute_migration(self) -> Dict[str, Any]:
        """
        Execute the complete 3-stage migration process.
        Returns status dictionary with results of each stage.
        """
        results = {}

        # Stage 1: Alter table schema
        try:
            schema_success = self.alter_table_schema()
            self.migration_status['schema_alteration'] = schema_success
            results['schema_alteration'] = {
                'status': 'success' if schema_success else 'failed',
                'message': 'Schema alteration completed'
            }
        except Exception as e:
            self.migration_status['schema_alteration'] = False
            results['schema_alteration'] = {
                'status': 'error',
                'message': f'Schema alteration failed: {str(e)}'
            }

        # Stage 2: Update ORM entity
