            results['orm_update'] = {
                'status': 'success' if orm_success else 'failed',
                'message': 'ORM entity update completed'
            }
        except Exception as e:
            self.migration_status['orm_update'] = False
            results['orm_update'] = {
                'status': 'error',
                'message': f'ORM update failed: {str(e)}'
            }

        # Stage 3: Adapt REST controller
        try:
            controller_success = self.adapt_rest_controller()
            self.migration_status['controller_adaptation'] = controller_success
            results['controller_adaptation'] = {
                'status': 'success' if controller_success else 'failed',
                'message': 'REST controller adaptation completed'
            }
        except Exception as e:
            self.migration_status['controller_adaptation'] = False
            results['controller_adaptation'] = {
                'status': 'error',
