import threading
import time
from collections import defaultdict

class DistributedLock:
    def __init__(self):
        self.locks = defaultdict(dict)
        self.locks['lock'] = defaultdict(lambda: None)

    def acquire(self, key, owner_id, lease_time=60):
        if key not in self.locks['lock']:
            self.locks['lock'][key] = {'owner': owner_id, 'expiry': time.time() + lease_time}
            print(f"Lock acquired by {owner_id} for key {key}")
            return True
        else:
            current_owner = self.locks['lock'][key]['owner']
            if current_owner == owner_id:
                print(f"Lock already held by {owner_id} for key {key}")
                return True
            else:
                print(f"Failed to acquire lock for key {key}. Currently held by {current_owner}")
                return False

    def release(self, key, owner_id):
        if key in self.locks['lock']:
            current_owner = self.locks['lock'][key]['owner']
            if current_owner == owner_id:
                del self.locks['lock'][key]
                print(f"Lock released by {owner_id} for key {key}")
                return True
            else:
                print(f"Failed to release lock for key {key}. Not held by {owner_id}")
                return False
        else:
            print(f"Failed to release lock for key {key}. Key does not exist")
            return False

    def renew_lease(self, key, owner_id):
        if key in self.locks['lock']:
            current_owner = self.locks['lock'][key]['owner']
            if current_owner == owner_id:
                self.locks['lock'][key]['expiry'] = time.time() + 60
                print(f"Lease renewed for key {key} by {owner_id}")
                return True
            else:
                print(f"Failed to renew lease for key {key}. Not held by {owner_id}")
                return False
        else:
            print(f"Failed to renew lease for key {key}. Key does not exist")
            return False

class HeartbeatDaemon:
    def __init__(self, lock_manager):
        self.lock_manager = lock_manager
        self.daemon_thread = threading.Thread(target=self.run, daemon=True)
        self.daemon_thread.start()

    def run(self):
        while True:
            for key in list(self.lock_manager.locks['lock'].keys()):
                if time.time() > self.lock_manager.locks['lock'][key]['expiry']:
                    print(f"Lock expired for key {key}. Releasing...")
                    self.lock_manager.release(key, self.lock_manager.locks['lock'][key]['owner'])
            time.sleep(5)  # Check every 5 seconds

