from collections import defaultdict
from typing import List, Dict, Set

class MigrationTask:
    def __init__(self, name: str):
        self.name = name
        self.dependencies: Set[str] = set()
        self.dependents: Set[str] = set()

    def add_dependency(self, task_name: str):
        self.dependencies.add(task_name)

    def add_dependent(self, task_name: str):
        self.dependents.add(task_name)

class EventBusMigrationPlan:
    def __init__(self):
        self.tasks: Dict[str, MigrationTask] = {}
        self.execution_order: List[str] = []

    def add_task(self, task_name: str, dependencies: List[str]):
        if task_name in self.tasks:
            raise ValueError(f"Task {task_name} already exists.")

        task = MigrationTask(task_name)
        for dep in dependencies:
            if dep not in self.tasks:
                raise ValueError(f"Dependency {dep} does not exist.")
            task.add_dependency(dep)
            self.tasks[dep].add_dependent(task_name)

        self.tasks[task_name] = task

    def get_execution_order(self) -> List[str]:
        if not self.execution_order:
            self._topological_sort()

        return self.execution_order

    def _topological_sort(self):
        visited: Set[str] = set()
        stack: List[str] = []

        def dfs(task_name: str):
            if task_name in visited:
                return
            visited.add(task_name)

            for dependent in self.tasks[task_name].dependents:
                dfs(dependent)

            stack.append(task_name)

        for task_name in self.tasks.keys():
            if task_name not in visited:
                dfs(task_name)

        self.execution_order = list(reversed(stack))

