    migration_plan.add_task("Task2", ["Task1"])
    migration_plan.add_task("Task3", ["Task1"])
    migration_plan.add_task("Task4", ["Task2", "Task3"])
    migration_plan.add_task("Task5", ["Task4"])

    # Get the execution order
    print(migration_plan.get_execution_order())  # Output: ['Task1', 'Task2', 'Task3', 'Task4', 'Task5']
